 let arr=(G8.units||[]).filter(u=>(S.refCountry==="all"||u.country===S.refCountry)&&(!nq||originSearchText(u).includes(nq)))
   .sort((a,b)=>a.label.localeCompare(b.label,"fr",{sensitivity:"base"})||a.country.localeCompare(b.country,"fr"));
